args.sparql:
SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Carson_City_Cyclone dbr:The_Winged_Horseman }
  ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = 'en')
  ?film dbo:director ?director .
  ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = 'en')
  OPTIONAL { ?director dbo:birthDate ?bd1 . }
  OPTIONAL { ?director dbp:birthDate ?bd2 . }
  BIND(COALESCE(?bd1, ?bd2) AS ?birthDate)
  FILTER(bound(?birthDate))
}
ORDER BY DESC(?birthDate)
LIMIT 1

